        if (ratelimitLookupPerSourceTemplate(conf, per_source_key_tpl_name, &shared->per_source_key_tpl,
                                             &shared->per_source_key_tpl_default) != RS_RET_OK) {
            if (per_source_key_tpl_name != NULL) {
